import type { Conversation, Message, Role } from "../core/schema.js";
import { scrubChatGPTUnicodeAndCitations } from "./unicode_scrubber.js";

const TURN_HEADER_REGEX = /^## Turn \d+:\s*(?:[^\w\s]*\s*)?(User|Assistant)\b/i;
const ATTACHMENT_REGEX = /\[Attached Document:\s*(.*?)\]/g;

/**
 * Parses markdown transcripts generated by scraping tools or browser extensions.
 * 
 * Enforces:
 * - Gotcha #5: Code-fence-aware turn header detection (never splits inside code blocks).
 * - Gotcha #14: Metadata parsing, trailing '---' removal, citation stripping, and turn audit.
 * - Gotcha #17: PUA Unicode scrubbing outside fences.
 */
export function parseScrapedMarkdown(content: string, id: string = "scraped-conv"): Conversation {
  // First, scrub leaked Unicode and inline citations outside fences
  const scrubbed = scrubChatGPTUnicodeAndCitations(content);
  const lines = scrubbed.text.split("\n");

  let title = "Untitled Conversation";
  let source = "scraped_md";
  let scrapedAt: string | null = null;
  let totalTurnsHeader: number | null = null;

  const attachments: string[] = [];

  // Parse header lines
  for (let i = 0; i < Math.min(lines.length, 30); i++) {
    const line = lines[i].trim();
    if (line.startsWith("# ") && title === "Untitled Conversation") {
      title = line.replace(/^#\s+/, "").trim();
    } else if (line.match(/^>\s*\*\*Source\*\*:\s*(.*)$/i)) {
      const match = line.match(/^>\s*\*\*Source\*\*:\s*(.*)$/i);
      if (match) source = match[1].trim();
    } else if (line.match(/^>\s*\*\*Scraped At\*\*:\s*(.*)$/i)) {
      const match = line.match(/^>\s*\*\*Scraped At\*\*:\s*(.*)$/i);
      if (match) scrapedAt = match[1].trim();
    } else if (line.match(/^>\s*\*\*Total Turns\*\*:\s*(\d+)$/i)) {
      const match = line.match(/^>\s*\*\*Total Turns\*\*:\s*(\d+)$/i);
      if (match) totalTurnsHeader = parseInt(match[1], 10);
    }
  }

  // Turn splitting state machine (fence-aware)
  interface RawTurn {
    role: Role;
    lines: string[];
  }

  const rawTurns: RawTurn[] = [];
  let currentTurn: RawTurn | null = null;
  let inFence = false;
  let fenceDelimiter = "";

  for (const line of lines) {
    const trimmed = line.trimStart();
    const fenceMatch = trimmed.match(/^(`{3,}|~{3,})/);

    if (fenceMatch) {
      const delim = fenceMatch[1];
      if (!inFence) {
        inFence = true;
        fenceDelimiter = delim[0];
      } else if (delim[0] === fenceDelimiter && delim.length >= 3) {
        inFence = false;
        fenceDelimiter = "";
      }
    }

    // Check for Turn header outside of code fences
    if (!inFence && TURN_HEADER_REGEX.test(trimmed)) {
      const match = trimmed.match(TURN_HEADER_REGEX);
      const roleStr = match ? match[1].toLowerCase() : "unknown";
      const role: Role = roleStr === "assistant" ? "assistant" : "user";

      if (currentTurn) {
        rawTurns.push(currentTurn);
      }
      currentTurn = { role, lines: [] };
      continue;
    }

    if (currentTurn) {
      currentTurn.lines.push(line);
    }
  }

  if (currentTurn) {
    rawTurns.push(currentTurn);
  }

  // Convert raw turns to canonical Message objects
  const messages: Message[] = [];

  for (let idx = 0; idx < rawTurns.length; idx++) {
    const turn = rawTurns[idx];
    let turnText = turn.lines.join("\n").trim();

    // Check for attachments
    turnText = turnText.replace(ATTACHMENT_REGEX, (_match, filename) => {
      const name = filename.trim();
      if (name && !attachments.includes(name)) {
        attachments.push(name);
      }
      return "";
    });

    // Strip trailing '---' divider (only one trailing separator)
    turnText = turnText.replace(/\n\s*---\s*$/, "").trim();

    if (turnText.length > 0) {
      messages.push({
        role: turn.role,
        content: turnText,
        id: `turn-${idx + 1}`,
      });
    }
  }

  const meta: Record<string, unknown> = {
    stripped_citations: scrubbed.strippedCitations,
    entities_replaced: scrubbed.entitiesReplaced,
  };

  if (scrapedAt) {
    meta.scraped_at = scrapedAt;
  }

  if (attachments.length > 0) {
    meta.attachments = attachments;
  }

  // Gotcha #14: Compare parsed turn count against Total Turns header
  if (totalTurnsHeader !== null && messages.length !== totalTurnsHeader) {
    meta.parse_warning = `Expected ${totalTurnsHeader} turns from header, but parsed ${messages.length} turns`;
  }

  return {
    id,
    source,
    title,
    messages,
    meta,
  };
}
